// lookup demo — Raw chicken (jahdb demo program)
var DATA={"Raw chicken":"Raw chicken keeps 1-2 days refrigerated, 9 months frozen. Never wash it \u2014 cooking kills bacteria."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("1-2 days"));

